-- Declare the seven SDA platform provider authorities as estate authority rows.
--
-- Each authority is retained byte-for-byte in source.content_object under its file
-- SHA-256 and declared as a selected AUTHORITY semantic definition whose semantics
-- name the stable authority id, the platform capability, the content digest, the
-- original source path and the known locators. The kernel boot read
-- `provider-authority` (kernel/semantic-authority/consumer/
-- sda-node-boot-data-access.authority.v1.json) resolves a binding's
-- providerAuthorityRef -- stable id, sourcePath or locator -- to these rows, so
-- the providers verify the same digest over row content and never dereference a
-- repository path.
--
-- Default: ROLLBACK. Replace the final ROLLBACK with COMMIT to install.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @trigger_name nvarchar(517), @triggers CURSOR;
SET @triggers=CURSOR LOCAL FAST_FORWARD FOR
 SELECT QUOTENAME(s.name)+N'.'+QUOTENAME(t.name)
 FROM sys.triggers t JOIN sys.objects o ON o.object_id=t.parent_id
 JOIN sys.schemas s ON s.schema_id=o.schema_id
 WHERE o.type='U' AND s.name IN ('model','source')
 AND (t.name LIKE 'guard%' OR t.name LIKE '%immutable%');
OPEN @triggers;
FETCH NEXT FROM @triggers INTO @trigger_name;
WHILE @@FETCH_STATUS=0 BEGIN EXEC(N'DROP TRIGGER '+@trigger_name); FETCH NEXT FROM @triggers INTO @trigger_name; END;
CLOSE @triggers; DEALLOCATE @triggers;
GO

-- profile-governed-json-authority-ingestor.v1
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @object bigint,@definition bigint,@digest binary(32),@bytes varbinary(max),@content_digest binary(32);
SET @;
SET @content_digest=HASHBYTES('SHA2_256',@bytes);
IF LOWER(CONVERT(varchar(64),@content_digest,2))<>N'99eaf0ae8e917f05c146f0b1794b5ddc1be17a81e070c54b9c520dfe29124063' THROW 51000,N'PROVIDER_AUTHORITY_DIGEST_MISMATCH:profile-governed-json-authority-ingestor.v1',1;
IF NOT EXISTS(SELECT 1 FROM source.content_object WHERE content_digest=@content_digest)
 INSERT source.content_object(content_digest,content_bytes,byte_length) VALUES(@content_digest,@bytes,DATALENGTH(@bytes));
IF (SELECT content_bytes FROM source.content_object WHERE content_digest=@content_digest)<>@bytes
 THROW 51000,N'PROVIDER_AUTHORITY_CONTENT_DIVERGED:profile-governed-json-authority-ingestor.v1',1;
EXEC model.put_semantic_definition 'AUTHORITY',N'sidefx:authorities',N'profile-governed-json-authority-ingestor.v1',N'{"authorityId":"profile-governed-json-authority-ingestor.v1","platformCapabilityId":"sda-json-authority-ingestion-port.v1","contentDigest":"sha256:99eaf0ae8e917f05c146f0b1794b5ddc1be17a81e070c54b9c520dfe29124063","sourcePath":"capabilities/sda-platform/bind-profile-governed-json-authority-ingestion/profile-governed-json-authority-ingestor.authority.json","locators":["../../../../scenario-driven-architecture/capabilities/sda-platform/bind-profile-governed-json-authority-ingestion/profile-governed-json-authority-ingestor.authority.json"]}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
IF NOT EXISTS (SELECT 1 FROM analysis.v_selected_semantic_definition d
 WHERE d.estate_model_pk=@estate AND d.object_kind='AUTHORITY' AND d.declared_id=N'profile-governed-json-authority-ingestor.v1'
  AND JSON_VALUE(d.definition_json,'$.semantics.contentDigest')=N'sha256:99eaf0ae8e917f05c146f0b1794b5ddc1be17a81e070c54b9c520dfe29124063'
  AND JSON_VALUE(d.definition_json,'$.semantics.sourcePath')=N'capabilities/sda-platform/bind-profile-governed-json-authority-ingestion/profile-governed-json-authority-ingestor.authority.json')
 THROW 51000,N'PROVIDER_AUTHORITY_DECLARATION_NOT_RESOLVED:profile-governed-json-authority-ingestor.v1',1;
IF NOT EXISTS (SELECT 1 FROM source.content_object co
 WHERE co.content_digest=@content_digest
  AND LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',co.content_bytes),2))=N'99eaf0ae8e917f05c146f0b1794b5ddc1be17a81e070c54b9c520dfe29124063')
 THROW 51000,N'PROVIDER_AUTHORITY_CONTENT_NOT_RETAINED:profile-governed-json-authority-ingestor.v1',1;
IF NOT EXISTS (SELECT 1 FROM analysis.v_selected_semantic_definition d
 CROSS APPLY OPENJSON(d.definition_json,'$.semantics.locators') l
 WHERE d.estate_model_pk=@estate AND d.object_kind='AUTHORITY' AND d.declared_id=N'profile-governed-json-authority-ingestor.v1'
  AND l.value=N'../../../../scenario-driven-architecture/capabilities/sda-platform/bind-profile-governed-json-authority-ingestion/profile-governed-json-authority-ingestor.authority.json')
 THROW 51000,N'PROVIDER_AUTHORITY_LOCATOR_NOT_RESOLVED:profile-governed-json-authority-ingestor.v1',1;
SELECT N'profile-governed-json-authority-ingestor.v1' AS authority_id,@definition AS definition_pk,
 LOWER(CONVERT(varchar(64),@content_digest,2)) AS content_digest,DATALENGTH(@bytes) AS byte_length;
GO

