 THROW 51000,N'PROVIDER_AUTHORITY_CONTENT_DIVERGED:os-environment-credential-conformance.v1',1;
EXEC model.put_semantic_definition 'AUTHORITY',N'sidefx:authorities',N'os-environment-credential-conformance.v1',N'{"authorityId":"os-environment-credential-conformance.v1","platformCapabilityId":"sda-os-environment-credential-port.v1","contentDigest":"sha256:53fa2f0d36b2086da9de40c2c6175895282e1632b92ed406eecbc8a81ad6140f","sourcePath":"capabilities/sda-platform/verify-os-environment-credential-conformance/conformance/os-environment-credential-conformance.v1.json","locators":["../../../../scenario-driven-architecture/capabilities/sda-platform/verify-os-environment-credential-conformance/conformance/os-environment-credential-conformance.v1.json"]}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
IF NOT EXISTS (SELECT 1 FROM analysis.v_selected_semantic_definition d
 WHERE d.estate_model_pk=@estate AND d.object_kind='AUTHORITY' AND d.declared_id=N'os-environment-credential-conformance.v1'
  AND JSON_VALUE(d.definition_json,'$.semantics.contentDigest')=N'sha256:53fa2f0d36b2086da9de40c2c6175895282e1632b92ed406eecbc8a81ad6140f'
  AND JSON_VALUE(d.definition_json,'$.semantics.sourcePath')=N'capabilities/sda-platform/verify-os-environment-credential-conformance/conformance/os-environment-credential-conformance.v1.json')
 THROW 51000,N'PROVIDER_AUTHORITY_DECLARATION_NOT_RESOLVED:os-environment-credential-conformance.v1',1;
IF NOT EXISTS (SELECT 1 FROM source.content_object co
 WHERE co.content_digest=@content_digest
  AND LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',co.content_bytes),2))=N'53fa2f0d36b2086da9de40c2c6175895282e1632b92ed406eecbc8a81ad6140f')
 THROW 51000,N'PROVIDER_AUTHORITY_CONTENT_NOT_RETAINED:os-environment-credential-conformance.v1',1;
IF NOT EXISTS (SELECT 1 FROM analysis.v_selected_semantic_definition d
 CROSS APPLY OPENJSON(d.definition_json,'$.semantics.locators') l
 WHERE d.estate_model_pk=@estate AND d.object_kind='AUTHORITY' AND d.declared_id=N'os-environment-credential-conformance.v1'
  AND l.value=N'../../../../scenario-driven-architecture/capabilities/sda-platform/verify-os-environment-credential-conformance/conformance/os-environment-credential-conformance.v1.json')
 THROW 51000,N'PROVIDER_AUTHORITY_LOCATOR_NOT_RESOLVED:os-environment-credential-conformance.v1',1;
SELECT N'os-environment-credential-conformance.v1' AS authority_id,@definition AS definition_pk,
 LOWER(CONVERT(varchar(64),@content_digest,2)) AS content_digest,DATALENGTH(@bytes) AS byte_length;
GO
SELECT declared_id AS authority_id,JSON_VALUE(definition_json,'$.semantics.contentDigest') AS content_digest
FROM analysis.v_selected_semantic_definition
WHERE estate_model_pk=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1)
 AND object_kind='AUTHORITY' AND declared_id IN (
  N'profile-governed-json-authority-ingestor.v1',N'profile-governed-proof-binding-evaluator.v1',N'scenario-semantic-carrier-validator-provider.v1',N'scenario-semantic-carrier-extractor-provider.v1',N'scenario-semantic-carrier-evaluator-provider.v1',N'deterministic-semantic-vector-indexer.v1',N'os-environment-credential-conformance.v1')
ORDER BY declared_id;
